cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# all tile options square/L in bounding 2x2
from collections import defaultdict
opts=[]
for r in range(6):
 for c in range(6):
  box={(r+i,c+j) for i in range(2) for j in range(2)}
  for n,typ in [(4,'square'),(3,'L')]:
   if len(box&cells)==n:
    shape=box&cells
    if typ=='square' or len(shape)==3:
     opts.append((shape,typ,r,c,box-shape))
# exact covers search
sol=[]
def go(rem, tiles):
 if not rem:
  sol.append(tiles); return
 x=min(rem)
 for opt in opts:
  sh,typ,r,c,miss=opt
  if x in sh and sh<=rem: go(rem-sh,tiles+[opt])
go(cells,[])
len(sol), [[(x[1],x[2],x[3],x[4]) for x in s] for s in sol[:10]]
